	@param1 int = 0,
	@param2 int
AS
	SELECT @param1, @param2
RETURN 0
```

Изменим скрипт следующим образом:

```sql
CREATE PROCEDURE [dbo].[GetUsersByCompany]
    @name nvarchar(50) 
AS
    SELECT * FROM Users 
    WHERE CompanyId=(SELECT Id FROM Companies WHERE Name=@name)
GO
